implementation.correct:
def allocate_bounded(requests, limits, total):
    allocations = [low for low, high in limits]
    spare = total - sum(allocations)
    if spare < 0:
        return None
    for i, (request, (low, high)) in enumerate(zip(requests, limits)):
        extra = min(max(0, min(request, high) - low), spare)
        allocations[i] += extra
        spare -= extra
    return allocations

