def rpn_variables(tokens, variables):
    stack = []
    for token in tokens:
        if token == 'neg':
            stack[-1] = -stack[-1]
        elif token == 'dup':
            stack.append(stack[-1])
        elif token == 'swap':
            stack[-2], stack[-1] = stack[-1], stack[-2]
        elif token in ('+', '-', '*', '/'):
            right, left = stack.pop(), stack.pop()
            if token == '+': value = left + right
            elif token == '-': value = left - right
            elif token == '*': value = left * right
            else:
                value = abs(left) // abs(right)
                if (left < 0) != (right < 0): value = -value
            stack.append(value)
        else:
            stack.append(variables[token[1:]] if token.startswith('$') else int(token))
    return stack[0]

