def window_top_k(words, window, k):
    counts = {}
    result = []
    for i, word in enumerate(words):
        counts[word] = counts.get(word, 0) + 1
        if i >= window:
            expired = words[i - window]
            counts[expired] -= 1
            if counts[expired] == 0:
                del counts[expired]
        result.append(sorted(counts, key=lambda item: (-counts[item], item))[:k])
    return result

