implementation.correct:
def settle_batches(initial, batches):
    balances = dict(initial)
    seen = set()
    committed = []
    for batch in batches:
        staged = dict(balances)
        pending = set(seen)
        accepted = True
        for transfer in batch:
            if transfer['id'] in pending:
                continue
            src, dst, amount = transfer['src'], transfer['dst'], transfer['amount']
            if staged[src] < amount:
                accepted = False
                break
            staged[src] -= amount
            staged[dst] += amount
            pending.add(transfer['id'])
        if accepted:
            balances, seen = staged, pending
        committed.append(accepted)
    return {'balances': balances, 'committed': committed, 'applied_ids': sorted(seen)}

