def resolve_layers(layers):
    merged = {}
    for layer in layers:
        for key, value in layer.items():
            if value is None:
                merged.pop(key, None)
            else:
                merged[key] = value
    done = {}
    def resolve(key, active):
        if key not in merged or key in active:
            raise ValueError('unresolved')
        if key in done:
            return done[key]
        value = merged[key]
        if isinstance(value, str):
            value = resolve(value[2:-1], active | {key})
        done[key] = value
        return value
    try:
        for key in merged:
            resolve(key, set())
    except ValueError:
        return {'ok': False, 'values': {}}
    return {'ok': True, 'values': done}

