    for i in range(len(left) + 1): table[i][0] = i * insertion
    for j in range(len(right) + 1): table[0][j] = j * insertion
    for i in range(1, len(left) + 1):
        for j in range(1, len(right) + 1):
            table[i][j] = min(table[i-1][j] + deletion, table[i][j-1] + insertion,
                              table[i-1][j-1] + (0 if left[i-1] == right[j-1] else substitution))
            if i >= 2 and j >= 2 and left[i-2] == right[j-1] and left[i-1] == right[j-2]:
                table[i][j] = min(table[i][j], table[i-2][j-2] + transpose)
    return table[-1][-1]

