def free_slots(busy, window, min_length):
    lower, upper = window
    cursor = lower
    free = []
    for start, end in sorted(busy):
        start, end = max(start, lower), min(end, upper)
        if start > end:
            continue
        if start > cursor:
            free.append([cursor, start - 1])
        cursor = max(cursor, end + 1)
    if cursor <= upper:
        free.append([cursor, upper])
    return [row for row in free if row[1] - row[0] + 1 >= min_length]

